// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Logout Revoke the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// AuthTelegram Sign in from the Telegram Mini App
	// (POST /auth/telegram)
	AuthTelegram(w http.ResponseWriter, r *http.Request)
	// ListConnections List connected applications
	// (GET /connections)
	ListConnections(w http.ResponseWriter, r *http.Request)
	// RevokeConnection Disconnect an application
	// (DELETE /connections/{id})
	RevokeConnection(w http.ResponseWriter, r *http.Request, id string)
	// GetHealth Service health and version
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetMe Current user profile and messenger bindings
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update the current user's settings
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListReminders List the reminders of the current user
	// (GET /reminders)
	ListReminders(w http.ResponseWriter, r *http.Request)
	// CreateReminder Create a reminder
	// (POST /reminders)
	CreateReminder(w http.ResponseWriter, r *http.Request)
	// DeleteReminder Delete a reminder
	// (DELETE /reminders/{id})
	DeleteReminder(w http.ResponseWriter, r *http.Request, id ReminderID)
	// GetReminder Get one reminder
	// (GET /reminders/{id})
	GetReminder(w http.ResponseWriter, r *http.Request, id ReminderID)
	// UpdateReminder Replace a reminder
	// (PUT /reminders/{id})
	UpdateReminder(w http.ResponseWriter, r *http.Request, id ReminderID)
	// CompleteReminder Confirm the pending occurrence
	// (POST /reminders/{id}/complete)
	CompleteReminder(w http.ResponseWriter, r *http.Request, id ReminderID)
	// ListTokens List personal access tokens
	// (GET /tokens)
	ListTokens(w http.ResponseWriter, r *http.Request)
	// CreateToken Create a personal access token
	// (POST /tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)
	// RevokeToken Revoke a personal access token
	// (DELETE /tokens/{id})
	RevokeToken(w http.ResponseWriter, r *http.Request, id TokenID)
}

